"use client";
import Link from "next/link";
import { useState } from "react";
import { Course, rankCourses, researchAreas } from "@/lib/data";
import { useApp } from "./app-provider";
import { Icon } from "./icon";
import { SaveCourse } from "./course-card";

export function CourseDetail({course}:{course:Course}) {
  const {profile}=useApp();const [tab,setTab]=useState("Overview");const [showAdvice,setShowAdvice]=useState(false);
  const ranked=rankCourses(profile).find(r=>r.course.id===course.id);
  const missing=course.prerequisiteIds.filter(id=>!profile.completed.includes(id));
  const related=researchAreas.filter(r=>course.research.includes(r.id));
  return <div className="page detail-page"><Link className="back-link" href="/courses"><Icon name="arrow" size={15} style={{transform:"rotate(180deg)"}}/>Back to courses</Link>
    <section className="detail-heading"><div><div className="eyebrow">{course.id} <span/> ILLUSTRATIVE COURSE PROFILE</div><h1>{course.title}</h1><p>{course.short}</p><div className="tag-list">{course.tags.map(tag=><span className="tag" key={tag}>{tag}</span>)}</div></div><span className={`detail-course-art ${course.color}`}><Icon name={course.icon} size={70}/></span></section>
    <div className="detail-stats"><div><Icon name="book" size={20}/><span><small>Units</small><strong>4 <span>sample</span></strong></span></div><div><Icon name="clock" size={20}/><span><small>Weekly workload</small><strong>{course.hours} hours <span>sample</span></strong></span></div><div><Icon name="code" size={20}/><span><small>Assessment style</small><strong>{course.format}</strong></span></div><div><Icon name="cap" size={20}/><span><small>Level</small><strong>{course.level}</strong></span></div></div>
    <div className="detail-grid"><div><div className="detail-tabs" role="tablist" aria-label="Course information">{["Overview","Topics & assessment","Student voices"].map(item=><button key={item} role="tab" id={`tab-${item.replaceAll(" ","-")}`} aria-controls="course-tabpanel" aria-selected={tab===item} className={tab===item?"selected":""} onClick={()=>setTab(item)}>{item}</button>)}</div>
    <div id="course-tabpanel" role="tabpanel" aria-labelledby={`tab-${tab.replaceAll(" ","-")}`} tabIndex={0}>
      {tab==="Overview"&&<><section className="detail-section"><h2>A closer look</h2><p>{course.description}</p><h3>What you could learn</h3><ul className="check-list">{course.outcomes.map(outcome=><li key={outcome}><Icon name="check" size={16}/>{outcome}</li>)}</ul></section><section className="detail-section"><h2>Before you get started</h2><p>{course.prerequisites}</p><div className={`prereq-note ${missing.length?"caution":"success"}`}><Icon name={missing.length?"info":"check"} size={18}/><div><strong>{missing.length?`Check sample prerequisites: ${missing.join(", ")}`:"No unmet prerequisites in the demo model"}</strong><p>Not an enrollment eligibility check. Confirm actual prerequisites, restrictions, and offerings with USC.</p></div></div></section><section className="detail-section"><h2>Where this could lead</h2><p>Connect your coursework with a question you’d like to explore.</p>{related.length?<div className="related-research">{related.map(area=><Link href={`/research#${area.id}`} key={area.id}><span className={`course-icon ${area.color}`}><Icon name="flask"/></span><span><small>DEMO RESEARCH DIRECTION</small><strong>{area.title}</strong></span><Icon name="arrow" size={18}/></Link>)}</div>:<p className="inline-note">No research directions are linked to this sample course yet. <Link href="/research">Explore all directions.</Link></p>}</section></>}
      {tab==="Topics & assessment"&&<><section className="detail-section"><h2>Ideas you’ll explore</h2><p>An illustrative topic outline, not an official syllabus.</p><ol className="topic-list">{course.topics.map((topic,i)=><li key={topic}><span>{String(i+1).padStart(2,"0")}</span>{topic}</li>)}</ol></section><section className="detail-section"><h2>Assessment breakdown</h2><p>Sample proportions for demonstrating learning-style preferences.</p><div className="assessment-bar" aria-hidden="true">{course.assessment.map((a,i)=><span key={a.label} style={{width:`${a.percent}%`,background:["#8d2434","#d7a75c","#b4c8bd"][i%3]}}/>)}</div><div className="assessment-legend">{course.assessment.map((a,i)=><div key={a.label}><span className="legend-dot" style={{background:["#8d2434","#d7a75c","#b4c8bd"][i%3]}}/><span>{a.label}</span><strong>{a.percent}%</strong></div>)}</div></section></>}
      {tab==="Student voices"&&<section className="detail-section"><h2>A little advice from someone who’s been there</h2><p>Fictional examples of opt-in senior guidance. No real students or reviews are represented.</p><article className="review-card"><span className="tiny-label">SAMPLE CONTRIBUTION · NOT A REAL REVIEW</span><blockquote>“Start with a small project you actually care about. Getting comfortable with the basics early makes it much easier to explore your own ideas later.”</blockquote><div className="review-author"><span className="avatar muted-avatar">S</span><span><strong>Sample senior</strong><small>Illustrative student profile</small></span></div><button type="button" className="btn secondary" onClick={()=>setShowAdvice(!showAdvice)} aria-expanded={showAdvice}>{showAdvice?"Hide sample advice":"Read preparation advice"}<Icon name="arrow" size={15}/></button>{showAdvice&&<div className="sample-advice"><strong>How I would prepare</strong><ul><li>Review the foundational skills mentioned in the official syllabus.</li><li>Set aside consistent study time instead of leaving projects to the last week.</li><li>Find classmates to discuss ideas with while following course collaboration rules.</li></ul><p>In a future version, students can opt into contact requests. This prototype does not contact anyone.</p></div>}</article></section>}
    </div></div>
    <aside className="detail-aside"><div className="panel fit-panel"><span className="light-label"><Icon name="spark" size={16}/>YOUR COURSE, IN CONTEXT</span><h2>Could this be your next step?</h2><ul className="check-list">{(ranked?.reasons??["You’ve marked this course as completed."]).map(reason=><li key={reason}><Icon name="check" size={15}/>{reason}</li>)}</ul>{course.hours>profile.workload&&<p className="workload-warning">The sample workload is {course.hours-profile.workload} hours above your preference.</p>}<SaveCourse course={course}/><Link className="btn secondary" href={`/chat?course=${course.slug}`}><Icon name="chat" size={16}/>Talk about this course</Link></div><div className="source-note"><Icon name="info" size={19}/><h3>Details matter.</h3><p>This page uses sample data, including workload, units, prerequisites, and assessment. Instructor, semester, and availability have not been verified.</p><a href="https://classes.usc.edu/" target="_blank" rel="noreferrer">Check USC’s official schedule <Icon name="external" size={14}/></a></div></aside></div>
  </div>;
}
